import { describe, it, expect, beforeEach } from "vitest";
import { renderHook, act } from "@testing-library/react";
import type React from "react";
import { createElement } from "react";
import { useSave, SaveProvider } from "./useSave";
import { getDefaultSave, saveSave } from "~/services/persistence";

// ── localStorage stub ──────────────────────────────────────────────
const store: Record<string, string> = {};

beforeEach(() => {
  for (const key of Object.keys(store)) delete store[key];
  Object.defineProperty(globalThis, "localStorage", {
    value: {
      getItem: (k: string) => store[k] ?? null,
      setItem: (k: string, v: string) => {
        store[k] = v;
      },
      removeItem: (k: string) => {
        delete store[k];
      },
    },
    writable: true,
    configurable: true,
  });
});

// ── Tests ──────────────────────────────────────────────────────────

describe("useSave", () => {
  it("returns default save data on first call", () => {
    const { result } = renderHook(() => useSave());
    expect(result.current.save).toEqual(getDefaultSave());
  });

  it("updateSave persists and updates React state", () => {
    const { result } = renderHook(() => useSave());

    act(() => {
      result.current.updateSave((s) => ({
        ...s,
        unlockedWorlds: [1, 2],
      }));
    });

    expect(result.current.save.unlockedWorlds).toEqual([1, 2]);
    // Also persisted to localStorage
    const stored = JSON.parse(store["luckypath_save"]);
    expect(stored.unlockedWorlds).toEqual([1, 2]);
  });

  it("completeLevel keeps the best clover count", () => {
    const { result } = renderHook(() => useSave());

    act(() => result.current.completeLevel("level-1", 2));
    expect(result.current.save.completedLevels["level-1"]).toBe(2);

    act(() => result.current.completeLevel("level-1", 1));
    expect(result.current.save.completedLevels["level-1"]).toBe(2);

    act(() => result.current.completeLevel("level-1", 3));
    expect(result.current.save.completedLevels["level-1"]).toBe(3);
  });
});

describe("SaveProvider", () => {
  function wrapper({ children }: { children: React.ReactNode }) {
    return createElement(SaveProvider, null, children);
  }

  it("shares a single save state across multiple useSave consumers", () => {
    // Render two independent useSave hooks under the same provider
    const { result: hookA } = renderHook(() => useSave(), { wrapper });
    const { result: hookB } = renderHook(() => useSave(), { wrapper });

    // Both should start with the same default
    expect(hookA.current.save).toEqual(getDefaultSave());
    expect(hookB.current.save).toEqual(getDefaultSave());
  });

  it("mutations through one consumer are visible to others via shared context", () => {
    // Use a single render that calls useSave twice to simulate co-mounted hooks
    const { result } = renderHook(
      () => {
        const first = useSave();
        const second = useSave();
        return { first, second };
      },
      { wrapper },
    );

    // Same reference — provider deduplicates
    expect(result.current.first.save).toBe(result.current.second.save);

    // Mutation through first is visible to second immediately
    act(() => {
      result.current.first.updateSave((s) => ({
        ...s,
        unlockedWorlds: [1, 2, 3],
      }));
    });

    expect(result.current.first.save.unlockedWorlds).toEqual([1, 2, 3]);
    expect(result.current.second.save.unlockedWorlds).toEqual([1, 2, 3]);
  });

  it("without provider, useSave creates standalone state (backward compatible)", () => {
    const { result } = renderHook(() => useSave());
    expect(result.current.save).toEqual(getDefaultSave());

    act(() => result.current.completeLevel("level-x", 2));
    expect(result.current.save.completedLevels["level-x"]).toBe(2);
  });
});

import { describe, it, expect } from "vitest";
import { useSave, SaveProvider } from "./useSave";
import type { UseSaveReturn } from "./useSave";

/**
 * useSave architectural contract tests.
 *
 * These tests verify the module's public API surface — that the shared
 * save context pattern exports the expected symbols and types. React
 * hook behavior is tested through the hooks that compose useSave
 * (useWorldSession, useRainbowEasterEgg) and integration/E2E tests.
 */

describe("useSave module exports", () => {
  it("exports useSave as a function", () => {
    expect(typeof useSave).toBe("function");
  });

  it("exports SaveProvider as a function (React component)", () => {
    expect(typeof SaveProvider).toBe("function");
  });

  it("UseSaveReturn interface covers save, setSave, updateSave, completeLevel", () => {
    // Type-level check: if UseSaveReturn is missing any expected key,
    // this assignment will fail at compile time.
    const shape: Record<keyof UseSaveReturn, true> = {
      save: true,
      setSave: true,
      updateSave: true,
      completeLevel: true,
    };
    expect(Object.keys(shape)).toHaveLength(4);
  });
});
